<?php
namespace App\Domains\Employee\Services;
use App\Domains\Employee\Events\EmployeeStatusChanged; use App\Domains\Employee\Models\Employee; use Illuminate\Support\Facades\DB; use Illuminate\Validation\ValidationException;
class EmployeeLifecycleService { public function transition(Employee $employee,string $status):Employee { $allowed=['draft'=>['pending_approval','active'],'pending_approval'=>['active','draft'],'active'=>['on_leave','suspended','resigned','terminated'],'on_leave'=>['active'],'suspended'=>['active','terminated'],'resigned'=>['archived'],'terminated'=>['archived'],'archived'=>[]]; if(!in_array($status,$allowed[$employee->employment_status]??[],true))throw ValidationException::withMessages(['employment_status'=>'Invalid employee lifecycle transition.']); return DB::transaction(function()use($employee,$status){$from=$employee->employment_status;$employee->update(['employment_status'=>$status]);$employee->timelines()->create(['event_type'=>'status_changed','title'=>'Employment status changed','description'=>"{$from} → {$status}",'old_values'=>['employment_status'=>$from],'new_values'=>['employment_status'=>$status],'occurred_at'=>now()]);EmployeeStatusChanged::dispatch($employee,$from,$status);return $employee;});} }
